fn clip(a: Vec<i8>, min: i8, max: i8) -> Vec<i8> {
    // Create a new vector to store the clipped values
    let mut result = Vec::with_capacity(a.len());

    // Iterate through each element in the input vector
    for &value in &a {
        // Clip the value according to the bounds
        let clipped_value = if value < min {
            min
        } else if value > max {
            max
        } else {
            value
        };
        // Push the clipped value to the result vector
        result.push(clipped_value);
    }

    // Return the result vector
    result
}